  str_senior_skin_draw_rule_reward_tips_gl = "ตารางด้านล่างแสดงความเป็นไปได้พื้นฐานของรางวัลทั้ง <color=#d24956>10</color> ชิ้น \nหลังจากได้รางวัลอย่างใดอย่างหนึ่งแล้ว จะนำค่าความเป็นไปได้พื้นฐานของรางวัลที่เหลือมาคำนวณค่าความเป็นไปได้ใหม่ (โดยผลรวมของความเป็นไปได้ยังคงเป็น <color=#d24956>100%</color>) <b><color=#696868>นักเดินทางทุกคนที่เข้าร่วมอีเวนต์จะมีความเป็นไปได้พื้นฐานเท่ากัน</color></b><b><color=#d59519>แตะที่ปุ่มความเป็นไปได้บนหน้าจอหลักเพื่อดูรายละเอียด</color></b>",
  str_senior_skin_draw_dp_title_gl = "ข้อมูลความเป็นไปได้—เที่ยวอควาเรียม",
  str_senior_skin_draw_rule_probability_detail = "นักเดินทางทุกคนที่เข้าร่วมอีเวนต์จะมีความเป็นไปได้พื้นฐานเท่ากันตามที่ได้อธิบายไว้ในกติกาแล้ว เนื่องจากแต่ละรางวัลสามารถรับได้เพียงครั้งเดียว ความเป็นไปได้ของการจับรางวัลที่เหลือจะถูกคำนวณใหม่แบบไดนามิกตามผลลัพธ์ที่ได้จากการอธิษฐานครั้งก่อนหน้า<b><color=#696868>หลักการของการเปลี่ยนแปลงความเป็นไปได้แบบไดนามิกคือ หลังจากปลดรางวัลที่ได้ออกไปแล้วระบบจะกระจายความเป็นไปได้ของรางวัลที่เหลือในอัตราส่วนที่เท่ากันตามจำนวนการอธิษฐานและความเป็นไปได้พื้นฐานข้างต้นโดยผลรวมของความเป็นไปได้เท่ากับ 1</color></b>",
  str_senior_skin_draw_rule_probability_tips = "<b><color=#d59519>การจับรางวัลนี้ใช้อัลกอริธึมความเป็นไปได้แบบไดนามิก\nความเป็นไปได้ของการอธิษฐานครั้งต่อไปของคุณคือ: </color></b>",
  str_senior_skin_draw_rule_get_probability = "โอกาสได้รับ",
  str_senior_skin_draw_rule_show_get_probability = "แสดงโอกาสได้รับ",
