  str_senior_skin_draw_rule_title_kr = "ภายใต้กฎสปอตไลท์",
  str_senior_skin_draw_rule_detail_kr = "○ รับประกันรางวัล <color=#d70500>1</color> สำหรับแต่ละความปรารถนา นักเดินเรือสามารถขอพรข้อแรกได้ฟรีและใช้ตั๋วภาพยนตร์เพื่อขอพรอีก <color=#d70500>9</color> ได้\n○ กิจกรรมมอบรางวัล <color=#d70500>10</color> ทั้งหมด ซึ่งแต่ละรางวัลสามารถรับได้ <color=#d70500>ครั้งเดียว</color> โดยไม่ซ้ำกัน เมื่อได้รับรางวัลจากความปรารถนาแล้ว จะถูกลบออกจากรางวัลรวมและจะไม่สามารถรับได้อีก ทำให้ <color=#d70500>10</color> ต้องการรับรางวัลทั้งหมด\n○ จำนวนตั๋วหนังที่ต้องใช้ในการขอพรแตกต่างกันไป <color=#d70500>ที่ 2</color> ถึง <color=#d70500>ที่ 10</color> ตามลำดับราคา <color=#d70500>1</color>, <color=#d70500>1</color> , <color=#d70500>2</color>, <color=#d70500>4</color>, <color=#d70500>6</color>, <color=#d70500>6</color>, <color=#d70500>10</color>, <color=#d70500>10</color> และ <color=#d70500>10</color> ตั๋วภาพยนตร์ ปริมาณที่ต้องการจะแสดงบนปุ่มสร้างความปรารถนา\n○ สามารถซื้อตั๋วหนังได้ เนื่องจากเป็นรายการที่มีเวลาจำกัด ตั๋วภาพยนตร์ที่ไม่ได้ใช้ในช่วงสิ้นสุดกิจกรรม <color=#f3bd3c>Under the Spotlight</color> จะถูกแปลงเป็น Lumamber <color=#d70500>100</color> โดยอัตโนมัติ โปรดตรวจสอบอีเมลของคุณอีกครั้ง <color=#d70500>1</color> ชั่วโมงหลังจากกิจกรรมสิ้นสุดลง",
  str_senior_skin_draw_rule_reward_detail_kr = "นักเดินเรือมีโอกาสได้รับชุดพิเศษ <color=#f3bd3c>เกิดมาเพื่อ พ.ร.บ</color> จาก <color=#d70500>วันที่ 6</color> ประสงค์ต่อไป. เครื่องแต่งกายและของรางวัลอื่น ๆ สามารถหาได้ภายใน <color=#d70500>10</color> ความปรารถนา\n\nรายการรางวัลทั้งหมดมีดังนี้:\nรางวัลสูงสุด: ชุดพิเศษของ Charon <color=#f3bd3c>เกิดมาเพื่อ พ.ร.บ</color> ×1. รางวัลซ้ำจะเปลี่ยนเป็น Lumamber ×3,000\nรางวัลหายาก: Lumamber ×<color=#d70500>600</color> + การตกแต่ง Cloud Gardens รุ่นลิมิเต็ดอิดิชั่น: <color=#f3bd3c>โคมไฟ Windelion</color> ×1. รางวัลซ้ำจะเปลี่ยนเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลหายาก: Lumamber ×<color=#d70500>600</color> + กรอบอวาตาร์ Limited Edition: <color=#f3bd3c>ที่คาดผมค้างคาว</color> ×1. รางวัลซ้ำจะเปลี่ยนเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลหายาก: Lumamber ×<color=#d70500>600</color> + อวาตาร์รุ่นลิมิเต็ดอิดิชั่น: <color=#f3bd3c>ชารอนนักแสดงมากความสามารถ</color> ×1 รางวัลซ้ำจะเปลี่ยนเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลขั้นสูง: Lumamber ×<color=#d70500>300</color> + <color=#f3bd3c>กล่องคำสั่งสีแดง IV</color> ×10\nรางวัลขั้นสูง: Lumamber ×<color=#d70500>300</color> + <color=#f3bd3c>กล่องคำสั่งแจสเปอร์ III</color> ×25\nรางวัลขั้นสูง: Lumamber ×<color=#d70500>300</color> + <color=#f3bd3c>ชุดรีชาร์จ</color> ×10\nรางวัลระดับกลาง: Lumamber ×<color=#d70500>200</color> + <color=#f3bd3c>กล่องคำสั่งแจสเปอร์ II</color> ×30\nรางวัลระดับกลาง: Lumamber ×<color=#d70500>200</color> + <color=#f3bd3c>ประเสริฐ</color> ×1,000\nรางวัลระดับกลาง: Lumamber ×<color=#d70500>200</color> + <color=#f3bd3c>ไนเตรียม</color> ×200,000",
  str_senior_skin_draw_rule_reward_tips_title_kr = "ความน่าจะเป็น",
  str_senior_skin_draw_rule_reward_tips_kr = "ตารางด้านล่างแสดงความน่าจะเป็นฐานของการได้รับ <color=#d70500>10</color> ผลตอบแทน\nเมื่อได้รับรางวัล ความน่าจะเป็นของรายการที่เหลือในกลุ่มจะถูกคำนวณใหม่โดยใช้ตัวเลขเริ่มต้นเหล่านี้ (รักษาผลรวมของความน่าจะเป็นที่ <color=#d70500>100%</color>). <b><color=#302f2f>ความน่าจะเป็นพื้นฐานจะเหมือนกันสำหรับเนวิเกเตอร์ทุกคนที่เข้าร่วมในกิจกรรม </color></b><b><color=#f3bd3c>แตะปุ่มตารางความน่าจะเป็นแบบไดนามิกในหน้าหลักเพื่อดูรายละเอียดเพิ่มเติม</color></b>",
  str_senior_skin_draw_dp_title_kr = "ภายใต้ข้อมูลความน่าจะเป็นแบบไดนามิกของสปอตไลท์",
  str_senior_skin_draw_rule_probability_detail_kr = "เนวิเกเตอร์ที่เข้าร่วมทั้งหมดขึ้นอยู่กับความน่าจะเป็นพื้นฐานเดียวกันกับรายละเอียดในกฎ เนื่องจากแต่ละรางวัลสามารถรับได้เพียงครั้งเดียว ความน่าจะเป็นในการออกรางวัลสำหรับรายการที่เหลือจะถูกคำนวณใหม่แบบไดนามิกเพื่อสะท้อนถึงผลการจับฉลากครั้งก่อน <b><color=#302f2f>หลักการของการเปลี่ยนแปลงความน่าจะเป็นแบบไดนามิกของเราคือ: เมื่อนำรางวัลที่ได้รับออกแล้ว ระบบจะคำนวณความน่าจะเป็นในการสุ่มรางวัลสำหรับรางวัลที่เหลือในอัตราส่วนที่เท่ากันตามจำนวนความปรารถนาที่ได้ทำไปแล้วและความน่าจะเป็นพื้นฐาน โดยรักษาผลรวมของความน่าจะเป็นไว้ที่ 1</color></b>",
  str_senior_skin_draw_rule_probability_tips_kr = "<b><color=#f3bd3c>การจับฉลากนี้ใช้อัลกอริธึมความน่าจะเป็นแบบไดนามิก ความน่าจะเป็นสำหรับความปรารถนาต่อไปของคุณคือ:</color></b>",
  str_senior_skin_draw_rule_probability_down_kr = "เครื่องนำทางอาจนำเสนอความน่าจะเป็นแบบไดนามิกที่แตกต่างกัน หากผู้เล่น A และผู้เล่น B ได้รับรางวัลเดียวกันสำหรับความปรารถนาที่ 1 ความน่าจะเป็นแบบไดนามิกสำหรับรางวัลที่เหลือจะเท่ากันสำหรับความปรารถนาที่ 2 อย่างไรก็ตาม หากผู้เล่น A และผู้เล่น C ได้รับรางวัลที่แตกต่างกันสำหรับความปรารถนาแรกของพวกเขา พวกเขาจะมีไอเท็มที่แตกต่างกันเหลืออยู่ในกลุ่มสำหรับความปรารถนาที่สอง ดังนั้น ความน่าจะเป็นแบบไดนามิกของรางวัลจะแตกต่างกัน หากมีคำถามใดๆ โปรดติดต่อฝ่ายบริการลูกค้าของเราได้ตลอดเวลา",
