  str_senior_skin_draw_rule_reward_detail_blh = "นักเดินเรือมีโอกาสได้รับชุดพิเศษ <color=#063c8e>อ้อมกอดของเมโลดี้แสนหวาน</color> จาก <color=#d70500>วันที่ 6</color> ประสงค์ต่อไป. สามารถรับเครื่องแต่งกายและรางวัลอื่น ๆ ทั้งหมดได้ภายใน <color=#d70500>10</color> ความปรารถนา\n\nรายการรางวัลทั้งหมดมีดังนี้:\nรางวัลสูงสุด: ชุดพิเศษของ Bethlehem <color=#063c8e>อ้อมกอดของเมโลดี้แสนหวาน</color> ×1. รายการที่ซ้ำกันจะถูกแปลงเป็น Lumamber ×3,000\nรางวัลหายาก: Lumamber ×<color=#d70500>600</color> + การตกแต่ง Cloud Gardens รุ่นลิมิเต็ดอิดิชั่น: <color=#063c8e>โซฟาภูเขาหิมะ</color> ×1. สำเนาจะถูกแปลงเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลหายาก: Lumamber ×<color=#d70500>600</color> + กรอบอวาตาร์ Limited Edition: <color=#063c8e>หูฟังดีว่า</color> ×1. สำเนาจะถูกแปลงเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลหายาก: Lumamber ×<color=#d70500>600</color> + อวาตาร์รุ่นลิมิเต็ดอิดิชั่น: <color=#063c8e>ภวังค์ของเบธเลเฮม</color> ×1. สำเนาจะถูกแปลงเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลขั้นสูง: Lumamber ×<color=#d70500>300</color> + <color=#063c8e>กล่องคำสั่งสีน้ำเงิน IV</color> ×10\nรางวัลขั้นสูง: Lumamber ×<color=#d70500>300</color> + <color=#063c8e>กล่องคำสั่งแจสเปอร์ III</color> ×25\nรางวัลขั้นสูง: Lumamber ×<color=#d70500>300</color> + <color=#063c8e>ชุดรีชาร์จ</color> ×10\nรางวัลระดับกลาง: Lumamber ×<color=#d70500>200</color> + <color=#063c8e>กล่องคำสั่งแจสเปอร์ II</color> ×30\nรางวัลระดับกลาง: Lumamber ×<color=#d70500>200</color> + <color=#063c8e>ประเสริฐ</color> ×1,000\nรางวัลระดับกลาง: Lumamber ×<color=#d70500>200</color> + <color=#063c8e>ไนเตรียม</color> ×200,000",
  str_senior_skin_draw_rule_reward_tips_title_blh = "ความเป็นไปได้:",
  str_senior_skin_draw_rule_reward_tips_blh = "ตารางด้านล่างแสดงความน่าจะเป็นพื้นฐานของการได้รับรางวัล <color=#d70500>10</color> เมื่อได้รับรางวัล ความน่าจะเป็นของรายการที่เหลือในกลุ่มจะถูกคำนวณใหม่โดยใช้ตัวเลขเริ่มต้นเหล่านี้ (รักษาผลรวมของความน่าจะเป็นที่ <color=#d70500>100%</color>) <b><color=#302f2f>ความน่าจะเป็นพื้นฐานจะเหมือนกันสำหรับเนวิเกเตอร์ทุกคนที่เข้าร่วมกิจกรรม</color></b> <b><color=#302f2f>แตะปุ่มตารางความน่าจะเป็นแบบไดนามิกในหน้าหลัก สำหรับรายละเอียดเพิ่มเติม</color></b>",
  str_senior_skin_draw_dp_title_blh = "Sweet Melody's Embrace Dynamic ข้อมูลความน่าจะเป็น",
