  str_senior_skin_draw_rule_title_qt = "กฎอีเวนต์ที่ชวนให้หลงใหล",
  str_senior_skin_draw_rule_detail_qt = "○<color=#d24956>1</color> รับประกันรางวัลสำหรับความปรารถนาแต่ละครั้ง นักเดินเรือสามารถขอพรแรกได้ฟรีและใช้แว่นตาเฮฟวี่เวทในการขอพร <color=#d24956>9</color> ความปรารถนามากขึ้น\n○ข้อเสนอกิจกรรม <color=#d24956>10</color> ของรางวัลทั้งหมดซึ่งแต่ละรายการสามารถรับได้ <color=#d24956>ครั้งหนึ่ง</color> ไม่มีการทำซ้ำ เมื่อได้รางวัลจากความปรารถนาแล้ว สิ่งนั้นจะถูกลบออกจากกลุ่มรางวัลและจะไม่ได้รับอีกต่อไป ทำ <color=#d24956>10</color> ปรารถนาจะได้รับรางวัลทั้งหมด\n○จำนวนแก้วเฮฟวี่เวตที่ต้องใช้ในการขอพรแต่ละครั้งจะแตกต่างกันไป เดอะ <color=#d24956>อันดับที่ 2</color> ถึง <color=#d24956>วันที่ 10</color> ต้องการค่าใช้จ่ายตามลำดับ <color=#d24956>1</color>, <color=#d24956>1</color>, <color=#d24956>2</color>, <color=#d24956>4</color>, <color=#d24956>6</color>, <color=#d24956>6</color>, <color=#d24956>10</color>, <color=#d24956>10</color>, และ <color=#d24956>10</color> แว่นตาเฮฟวี่เวท จำนวนที่ต้องการจะแสดงบนปุ่มสร้างความปรารถนา\n○สามารถซื้อแว่นตาแบบหนาได้ ในฐานะที่เป็นรายการจำกัดเวลา แว่นตาเฮฟวี่เวตที่ยังไม่ได้ใช้ภายในสิ้นปี <color=#e89416>เหตุการณ์ที่น่าหลงใหล</color> เหตุการณ์จะถูกแปลงเป็นโดยอัตโนมัติ <color=#d24956>100</color> ลัมเบอร์. กรุณาตรวจสอบจดหมายของคุณสำหรับมัน <color=#d24956>1</color> ชั่วโมงหลังจากกิจกรรมสิ้นสุดลง",
  str_senior_skin_draw_rule_reward_detail_qt = "นักเร่งทางมีโอกาสได้ชุดพิเศษ <color=#e89416>ทิปซี่ วิมซี่</color> จากคำขอครั้งที่ <color=#d24956>6</color> เป็นต้นไป ชุดและรางวัลอื่น ๆ สามารถรับได้ภายใน <color=#d24956>10</color> คำขอ\n\nรายการรางวัลทั้งหมด ดังนี้:\nรางวัลชั้นนำ: ชุดพิเศษของ Azure <color=#e89416>ทิปซี่ วิมซี่</color> ×1 สำเนาซ้ำจะถูกแปลงเป็น Lumamber ×3,000\nรางวัลหายาก: Lumamber ×<color=#d24956>600</color> + ของตกแต่ง Cloud Gardens ฉบับจำกัด: <color=#e89416>โซฟาผู้กำกับ</color> ×1 สำเนาซ้ำจะถูกแปลงเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลหายาก: Lumamber ×<color=#d24956>600</color> + กรอบอวตารฉบับจำกัด: <color=#e89416>แว่นตาจริง</color> ×1 สำเนาซ้ำจะถูกแปลงเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลหายาก: Lumamber ×<color=#d24956>600</color> + อวตารฉบับจำกัด: <color=#e89416>เหยื่อของ Azure</color> ×1 สำเนาซ้ำจะถูกแปลงเป็น Lumamber ×600 + Special Star Flare ×1\nรางวัลขั้นสูง: Lumamber ×<color=#d24956>300</color> + <color=#e89416>กล่องคำสั่งสีน้ำเงิน IV</color> ×10\nรางวัลขั้นสูง: Lumamber ×<color=#d24956>300</color> + <color=#e89416>กล่องคำสั่งแจสเปอร์ III</color> ×25\nรางวัลขั้นสูง: Lumamber ×<color=#d24956>300</color> + <color=#e89416>แพ็คเติมพลัง</color> ×10\nรางวัลขั้นกลาง: Lumamber ×<color=#d24956>200</color> + <color=#e89416>กล่องคำสั่งแจสเปอร์ II</color> ×30\nรางวัลขั้นกลาง: Lumamber ×<color=#d24956>200</color> + <color=#e89416>สุดยอด</color> ×1,000\nรางวัลขั้นกลาง: Lumamber ×<color=#d24956>200</color> + <color=#e89416>ไนเทียม</color> ×200,000",
  str_senior_skin_draw_rule_reward_tips_title_qt = "ความน่าจะเป็น",
  str_senior_skin_draw_rule_reward_tips_qt = "ตารางด้านล่างแสดงความน่าจะเป็นพื้นฐานของการได้รับ <color=#d24956>10</color> รางวัล\nเมื่อได้รับรางวัล ความน่าจะเป็นของรายการที่เหลือในกลุ่มจะถูกคำนวณใหม่ตามโดยใช้ตัวเลขเริ่มต้นเหล่านี้ (รักษาผลรวมของความน่าจะเป็นที่ <color=#d24956>100%</color>). <b>ความน่าจะเป็นพื้นฐานจะเหมือนกันสำหรับเนวิเกเตอร์ทุกคนที่เข้าร่วมในกิจกรรม </b><b>แตะปุ่มตารางความน่าจะเป็นแบบไดนามิกในหน้าหลักเพื่อดูรายละเอียดเพิ่มเติม</b>",
  str_senior_skin_draw_dp_title_qt = "ข้อมูลความน่าจะเป็นแบบไดนามิกที่ชวนให้หลงใหล",
  str_senior_skin_draw_rule_probability_detail_qt = "Navigator ที่เข้าร่วมทั้งหมดอยู่ภายใต้ความน่าจะเป็นพื้นฐานเดียวกันตามรายละเอียดในกฎ เนื่องจากสามารถรับรางวัลแต่ละรายการได้เพียงครั้งเดียว ความน่าจะเป็นในการจับรางวัลสำหรับรายการที่เหลือจะถูกคำนวณใหม่แบบไดนามิกเพื่อสะท้อนผลการจับรางวัลครั้งก่อน <b>หลักการของการเปลี่ยนแปลงความน่าจะเป็นแบบไดนามิกของเราคือ: เมื่อรางวัลที่ได้รับถูกลบออก ระบบจะคำนวณความน่าจะเป็นในการจับรางวัลใหม่สำหรับรางวัลที่เหลือในอัตราส่วนที่เท่ากันตามจำนวนคำอธิษฐานที่ทำไปแล้วและความน่าจะเป็นพื้นฐาน โดยคงผลรวมของความน่าจะเป็นไว้ที่ 1</b>",
  str_senior_skin_draw_rule_probability_tips_qt = "<b><color=#e89416>การจับฉลากนี้ใช้อัลกอริธึมความน่าจะเป็นแบบไดนามิก ความน่าจะเป็นสำหรับความปรารถนาต่อไปของคุณคือ:</color></b>",
  str_senior_skin_draw_rule_probability_down_qt = "เนวิเกเตอร์อาจนำเสนอความน่าจะเป็นแบบไดนามิกที่แตกต่างกัน หากผู้เล่น A และผู้เล่น B ได้รับรางวัลเดียวกันสำหรับความปรารถนาที่ 1 ความน่าจะเป็นแบบไดนามิกสำหรับรางวัลที่เหลือจะเท่ากันสำหรับความปรารถนาที่ 2 อย่างไรก็ตาม หากผู้เล่น A และผู้เล่น C ได้รับรางวัลที่แตกต่างกันสำหรับความปรารถนาแรกของพวกเขา พวกเขาจะมีไอเท็มที่แตกต่างกันเหลืออยู่ในกลุ่มสำหรับความปรารถนาที่สอง ดังนั้น ความน่าจะเป็นแบบไดนามิกของรางวัลจะแตกต่างกัน หากมีคำถามใดๆ โปรดติดต่อฝ่ายบริการลูกค้าของเราได้ตลอดเวลา",
